//! rustty-vt-c sgr
//!
//! PORTS: ghostty src/terminal/c/sgr.zig
//!
//! PORT STATUS: done
//!
//! This module also hosts the hand-authored C ABI tagged-union surface for
//! `sgr.Attribute` (`Attribute.C`/`Tag`/`CValue`/`cval`), the
//! `Attribute.Unknown.C`/`cval`, and `Underline.C`/`cval`. In ghostty these are
//! generated by `lib.TaggedUnion(lib.target, Attribute, [8]u64)` and the small
//! per-type `cval` helpers, available only when the target produces C values
//! (`rustty_vt::sgr` carries them as comments — the C ABI projection lives here).

// PORT NOTE: the reference imports are
//   const std = @import("std");
//   const testing = std.testing;
//   const Allocator = std.mem.Allocator;
//   const lib = @import("../lib.zig");
//   const CAllocator = lib.alloc.Allocator;
//   const sgr = @import("../sgr.zig");
//   const Result = @import("result.zig").Result;
// `sgr` is rustty-vt's `sgr` module (the source of truth); `CAllocator` is
// `rustty_lib::allocator::Allocator`; `Result` is the sibling `result` module.

use crate::cwrap::{create, destroy};
use crate::result::Result;
use rustty_lib::allocator::{default, Alignment, Allocator as CAllocator, ZigSlice};
use rustty_vt::color;
use rustty_vt::sgr;
use std::mem::{align_of, size_of};
use std::os::raw::c_int;

// const log = std.log.scoped(.sgr);
//
// S177-F1/S5-F1: the sgr_set_params separator-overflow warning below used to
// bypass the C-ABI log sink with a raw, unconditional `eprintln!`, which an
// embedder that installed a log callback via
// `rustty_sys_set(RUSTTY_SYS_OPT_LOG, ...)` never saw. Routed through
// `sys::log_fn` under this scope constant, the `@tagName` of the reference's
// `std.log.scoped(.sgr)`.
pub(crate) const LOG_SCOPE: &str = "sgr";

// =====================================================================
// C ABI projection of sgr.Attribute (the `lib.TaggedUnion` surface).
//
// PORT NOTE: `rustty_vt::sgr` defers the C ABI types to this crate (see its
// `Attribute` PORT NOTE). We author them by hand following the
// `lib.TaggedUnion(lib.target, Attribute, [8]u64)` expansion: an `extern union`
// `CValue` with one member per tag (each typed as the tag's payload, using the
// payload's `.C` projection when it has one), plus a PINNED `_padding: [8]u64`,
// and a `#[repr(C)]` `C` struct `{ tag: Tag, value: CValue }`. The `[8]u64`
// padding is verbatim from the reference comment ("Largest variant is Unknown.C:
// 2 pointers + 2 usize = 32 bytes on 64-bit. We use [8]u64 (64 bytes) to allow
// room for future expansion while maintaining ABI compatibility.") and must
// NEVER change (ABI stability).
// =====================================================================

/// The C ABI value of `Underline`.
// pub const C = c_int;  (on `sgr.Attribute.Underline`)
pub type UnderlineC = c_int;

/// `Underline.cval`: the integer value of the underline style.
// pub fn cval(self: Underline) Underline.C { return @intFromEnum(self); }
pub fn underline_cval(self_: sgr::Underline) -> UnderlineC {
    // @intFromEnum(self) — `Underline` is `enum(u3)` 0..=5; widen to `c_int`.
    self_ as UnderlineC
}

/// The C ABI struct of `Attribute.Unknown`.
// pub const C = extern struct { full_ptr, full_len, partial_ptr, partial_len };
#[repr(C)]
#[derive(Clone, Copy)]
pub struct UnknownC {
    pub full_ptr: *const u16,
    pub full_len: usize,
    pub partial_ptr: *const u16,
    pub partial_len: usize,
}

/// `Unknown.cval`: the C ABI projection of the two raw `[]const u16` slices.
// pub fn cval(self: Unknown) Unknown.C {
//     return .{ .full_ptr = self.full.ptr, .full_len = self.full.len,
//               .partial_ptr = self.partial.ptr, .partial_len = self.partial.len };
// }
pub fn unknown_cval(self_: sgr::Unknown<'_>) -> UnknownC {
    UnknownC {
        full_ptr: self_.full.as_ptr(),
        full_len: self_.full.len(),
        partial_ptr: self_.partial.as_ptr(),
        partial_len: self_.partial.len(),
    }
}

/// C: RusttySgrAttributeTag (R2) — checked by the A5 enum-discriminant arm.
/// The C ABI compatible tag type for `Attribute`.
// PORT NOTE: `Attribute.Tag = lib.Enum(lib.target, &.{ "unset", "unknown",
// "bold", "reset_bold", "italic", "reset_italic", "faint", "underline",
// "underline_color", "256_underline_color", "reset_underline_color", "overline",
// "reset_overline", "blink", "reset_blink", "inverse", "reset_inverse",
// "invisible", "reset_invisible", "strikethrough", "reset_strikethrough",
// "direct_color_fg", "direct_color_bg", "8_bg", "8_fg", "reset_fg", "reset_bg",
// "8_bright_bg", "8_bright_fg", "256_bg", "256_fg" })`. For the C target this is a
// fieldless `enum(c_int)` with the keys in declaration order (`rustty_vt::sgr`'s
// `Attribute` Rust enum carries the same variants in the same order).
#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Tag {
    Unset = 0,
    Unknown = 1,
    Bold = 2,
    ResetBold = 3,
    Italic = 4,
    ResetItalic = 5,
    Faint = 6,
    Underline = 7,
    UnderlineColor = 8,
    Color256Underline = 9, // "256_underline_color"
    ResetUnderlineColor = 10,
    Overline = 11,
    ResetOverline = 12,
    Blink = 13,
    ResetBlink = 14,
    Inverse = 15,
    ResetInverse = 16,
    Invisible = 17,
    ResetInvisible = 18,
    Strikethrough = 19,
    ResetStrikethrough = 20,
    DirectColorFg = 21,
    DirectColorBg = 22,
    Color8Bg = 23, // "8_bg"
    Color8Fg = 24, // "8_fg"
    ResetFg = 25,
    ResetBg = 26,
    Color8BrightBg = 27, // "8_bright_bg"
    Color8BrightFg = 28, // "8_bright_fg"
    Color256Bg = 29,     // "256_bg"
    Color256Fg = 30,     // "256_fg"
}

/// The C ABI compatible union value type for `Attribute` (`Attribute.CValue`).
// PORT NOTE: `lib.TaggedUnion` builds an `extern union` with one field per tag.
// Payloadless tags have a `void` payload in the reference; Rust `#[repr(C)]`
// unions cannot hold a `()` member, so those tags ride the `_padding` (as in the
// `point`/`terminal` hand-authored unions). Payload-bearing members use the
// payload's `.C` projection: `unknown: Unknown.C`, `underline: Underline.C`
// (= `c_int`), the RGB-carrying tags use `color::RGB` (its `.C` is the
// byte-identical `extern struct { r, g, b }`), the `Name`-carrying tags use
// `color.Name.C` (= `u8`), and the `u8`-carrying tags use `u8`.
#[repr(C)]
#[derive(Clone, Copy)]
pub union CValue {
    pub unknown: UnknownC,
    pub underline: UnderlineC,
    pub underline_color: color::RGB,
    /// "256_underline_color"
    pub color_256_underline: u8,
    pub direct_color_fg: color::RGB,
    pub direct_color_bg: color::RGB,
    /// "8_bg" — `color.Name.C` is `u8`.
    pub color_8_bg: u8,
    /// "8_fg"
    pub color_8_fg: u8,
    /// "8_bright_bg"
    pub color_8_bright_bg: u8,
    /// "8_bright_fg"
    pub color_8_bright_fg: u8,
    /// "256_bg"
    pub color_256_bg: u8,
    /// "256_fg"
    pub color_256_fg: u8,
    /// Padding to the PINNED ABI size. `[8]u64` (64 bytes) per the reference.
    pub _padding: [u64; 8],
}

/// PORT NOTE (RECONCILIATION O3, `9673a22b0` ABI manifest): the reference's
/// `Attribute.C` becomes `lib.TaggedUnion(lib.target, @This(), .{ .padding =
/// [8]u64, .field_renames = .{ .@"256_underline_color" =
/// "underline_color_256", .@"8_bg" = "bg_8", .@"8_fg" = "fg_8",
/// .@"8_bright_bg" = "bright_bg_8", .@"8_bright_fg" = "bright_fg_8",
/// .@"256_bg" = "bg_256", .@"256_fg" = "fg_256" } })` (sgr.zig) — the 7
/// digit-leading Zig tag names get C-header-legal value-field names. This
/// table is `Attribute.C.cFieldRename` evaluated over the tag declaration
/// order (rename ?? (payload-less -> null) ?? tag name), consumed by
/// `types.rs` for the `RusttySgrAttribute` tagged-union arms and the deduped
/// `RusttySgrAttributeValue` union fields. The rename OPTIONS machinery
/// itself lives in `rustty_lib::union` (`UnionField::rename` +
/// `TaggedUnion::c_field_rename`).
pub const C_FIELD_ARMS: &[(&str, Option<&str>)] = &[
    ("unset", None),
    ("unknown", Some("unknown")),
    ("bold", None),
    ("reset_bold", None),
    ("italic", None),
    ("reset_italic", None),
    ("faint", None),
    ("underline", Some("underline")),
    ("underline_color", Some("underline_color")),
    // .@"256_underline_color" = "underline_color_256",
    ("256_underline_color", Some("underline_color_256")),
    ("reset_underline_color", None),
    ("overline", None),
    ("reset_overline", None),
    ("blink", None),
    ("reset_blink", None),
    ("inverse", None),
    ("reset_inverse", None),
    ("invisible", None),
    ("reset_invisible", None),
    ("strikethrough", None),
    ("reset_strikethrough", None),
    ("direct_color_fg", Some("direct_color_fg")),
    ("direct_color_bg", Some("direct_color_bg")),
    // .@"8_bg" = "bg_8",
    ("8_bg", Some("bg_8")),
    // .@"8_fg" = "fg_8",
    ("8_fg", Some("fg_8")),
    ("reset_fg", None),
    ("reset_bg", None),
    // .@"8_bright_bg" = "bright_bg_8",
    ("8_bright_bg", Some("bright_bg_8")),
    // .@"8_bright_fg" = "bright_fg_8",
    ("8_bright_fg", Some("bright_fg_8")),
    // .@"256_bg" = "bg_256",
    ("256_bg", Some("bg_256")),
    // .@"256_fg" = "fg_256",
    ("256_fg", Some("fg_256")),
];

/// C: GhosttySgrAttribute -> RusttySgrAttribute (R2) — the hand-authored tagged union (`Attribute.C`).
// pub const C = extern struct { tag: Tag, value: CValue };
#[repr(C)]
#[derive(Clone, Copy)]
pub struct AttributeC {
    /// D11 (P3-W6 T2): held as the C integer, NOT as `Tag`.
    /// `rustty_sgr_attribute_tag` takes `AttributeC` BY VALUE, so a `Tag`-typed
    /// field is materialized by the callee prologue and an undeclared value is
    /// UB there — even though nothing in this crate DISPATCHES on an inbound
    /// tag. That is the subtle part of this rule: the UB is in the
    /// materialization, not in the use, so "we never read it" is not a defence.
    /// `attribute_tag` remains the reference's pure pass-through (`return
    /// attr.tag;`) and therefore needs no narrowing point; `cval` writes the
    /// discriminant with `as c_int`.
    pub tag: c_int,
    pub value: CValue,
}

// BUILD-failure gate (D2): pin the `[8]u64` padding size, the natural alignment,
// and the `c_int`-width tag. Drift here fails the build.
const _: () = assert!(size_of::<CValue>() == size_of::<[u64; 8]>());
const _: () = assert!(align_of::<CValue>() == 8);
const _: () = assert!(size_of::<Tag>() == size_of::<c_int>());

impl AttributeC {
    /// `Attribute.cval`: convert a native `Attribute` into its C ABI tagged
    /// union. Payloadless tags leave the union value as raw padding (their tag
    /// alone carries the meaning); payload tags fill the matching member,
    /// applying the payload's `cval` where it has one.
    // pub const cval = c_union.cval;
    pub fn cval(attr: sgr::Attribute<'_>) -> AttributeC {
        // PORT NOTE: `lib.TaggedUnion.cval` does `@unionInit(CValue, @tagName(tag),
        // v.cval()-or-v)` then `.{ .tag = @as(Tag, self), .value = value }`. We
        // mirror it per variant. Payloadless variants get a zeroed value (the
        // padding) since their union member is `void`.
        // SAFETY: `[u64; 8]` is valid for any bit pattern; zero is a valid init
        // for the padding-riding payloadless variants.
        let zero = CValue {
            _padding: [0u64; 8],
        };
        match attr {
            sgr::Attribute::Unset => AttributeC {
                tag: Tag::Unset as c_int,
                value: zero,
            },
            sgr::Attribute::Unknown(v) => AttributeC {
                tag: Tag::Unknown as c_int,
                value: CValue {
                    unknown: unknown_cval(v),
                },
            },
            sgr::Attribute::Bold => AttributeC {
                tag: Tag::Bold as c_int,
                value: zero,
            },
            sgr::Attribute::ResetBold => AttributeC {
                tag: Tag::ResetBold as c_int,
                value: zero,
            },
            sgr::Attribute::Italic => AttributeC {
                tag: Tag::Italic as c_int,
                value: zero,
            },
            sgr::Attribute::ResetItalic => AttributeC {
                tag: Tag::ResetItalic as c_int,
                value: zero,
            },
            sgr::Attribute::Faint => AttributeC {
                tag: Tag::Faint as c_int,
                value: zero,
            },
            sgr::Attribute::Underline(v) => AttributeC {
                tag: Tag::Underline as c_int,
                value: CValue {
                    underline: underline_cval(v),
                },
            },
            sgr::Attribute::UnderlineColor(v) => AttributeC {
                tag: Tag::UnderlineColor as c_int,
                value: CValue { underline_color: v },
            },
            sgr::Attribute::Color256Underline(v) => AttributeC {
                tag: Tag::Color256Underline as c_int,
                value: CValue {
                    color_256_underline: v,
                },
            },
            sgr::Attribute::ResetUnderlineColor => AttributeC {
                tag: Tag::ResetUnderlineColor as c_int,
                value: zero,
            },
            sgr::Attribute::Overline => AttributeC {
                tag: Tag::Overline as c_int,
                value: zero,
            },
            sgr::Attribute::ResetOverline => AttributeC {
                tag: Tag::ResetOverline as c_int,
                value: zero,
            },
            sgr::Attribute::Blink => AttributeC {
                tag: Tag::Blink as c_int,
                value: zero,
            },
            sgr::Attribute::ResetBlink => AttributeC {
                tag: Tag::ResetBlink as c_int,
                value: zero,
            },
            sgr::Attribute::Inverse => AttributeC {
                tag: Tag::Inverse as c_int,
                value: zero,
            },
            sgr::Attribute::ResetInverse => AttributeC {
                tag: Tag::ResetInverse as c_int,
                value: zero,
            },
            sgr::Attribute::Invisible => AttributeC {
                tag: Tag::Invisible as c_int,
                value: zero,
            },
            sgr::Attribute::ResetInvisible => AttributeC {
                tag: Tag::ResetInvisible as c_int,
                value: zero,
            },
            sgr::Attribute::Strikethrough => AttributeC {
                tag: Tag::Strikethrough as c_int,
                value: zero,
            },
            sgr::Attribute::ResetStrikethrough => AttributeC {
                tag: Tag::ResetStrikethrough as c_int,
                value: zero,
            },
            sgr::Attribute::DirectColorFg(v) => AttributeC {
                tag: Tag::DirectColorFg as c_int,
                value: CValue { direct_color_fg: v },
            },
            sgr::Attribute::DirectColorBg(v) => AttributeC {
                tag: Tag::DirectColorBg as c_int,
                value: CValue { direct_color_bg: v },
            },
            sgr::Attribute::Color8Bg(v) => AttributeC {
                tag: Tag::Color8Bg as c_int,
                value: CValue {
                    color_8_bg: v.cval(),
                },
            },
            sgr::Attribute::Color8Fg(v) => AttributeC {
                tag: Tag::Color8Fg as c_int,
                value: CValue {
                    color_8_fg: v.cval(),
                },
            },
            sgr::Attribute::ResetFg => AttributeC {
                tag: Tag::ResetFg as c_int,
                value: zero,
            },
            sgr::Attribute::ResetBg => AttributeC {
                tag: Tag::ResetBg as c_int,
                value: zero,
            },
            sgr::Attribute::Color8BrightBg(v) => AttributeC {
                tag: Tag::Color8BrightBg as c_int,
                value: CValue {
                    color_8_bright_bg: v.cval(),
                },
            },
            sgr::Attribute::Color8BrightFg(v) => AttributeC {
                tag: Tag::Color8BrightFg as c_int,
                value: CValue {
                    color_8_bright_fg: v.cval(),
                },
            },
            sgr::Attribute::Color256Bg(v) => AttributeC {
                tag: Tag::Color256Bg as c_int,
                value: CValue { color_256_bg: v },
            },
            sgr::Attribute::Color256Fg(v) => AttributeC {
                tag: Tag::Color256Fg as c_int,
                value: CValue { color_256_fg: v },
            },
        }
    }
}

// =====================================================================
// The C API.
// =====================================================================

/// Wrapper around parser that tracks the allocator for C API usage.
// PORT NOTE: the reference `ParserWrapper` is `struct { parser: sgr.Parser,
// alloc: Allocator }` where `parser.params` is an `[]const u16` the C API owns
// (allocated by `setParams`, freed by `free`). rustty's `sgr::Parser<'a>` borrows
// `params: &'a [u16]`, so the wrapper itself must own the backing `u16` buffer
// (the moral equivalent of the reference's owned slice). We hold that buffer as a
// raw `(ptr, len)` the wrapper manages directly — mirroring the reference's
// manual `alloc.dupe`/`alloc.free` — and a `parser: sgr::Parser<'static>` whose
// `params` field points into it. The stored `alloc: Option<CAllocator>` is the
// original (possibly null) C allocator (see `cwrap` PORT NOTE) used to free both
// the buffer and the wrapper.
pub struct ParserWrapper {
    parser: sgr::Parser<'static>,
    /// Owned backing buffer for `parser.params` (the reference's owned
    /// `[]const u16`). Empty (`null`/`0`) when no params are set.
    params_ptr: *mut u16,
    params_len: usize,
    alloc: Option<CAllocator>,
}

/// C: GhosttySgrParser -> RusttySgrParser (R2)
// pub const Parser = ?*ParserWrapper;
pub type Parser = *mut ParserWrapper;

/// PORT NOTE: `pub fn new(alloc_, result) callconv(...) Result`.
///
/// # Safety
/// `alloc_`, if non-null, must point to a valid `CAllocator`; `result` must be a
/// valid, writable pointer to `Parser`.
pub unsafe fn new(alloc_: Option<&CAllocator>, result: *mut Parser) -> Result {
    // const ptr = alloc.create(ParserWrapper) catch return .out_of_memory;
    let ptr = unsafe {
        create(
            alloc_,
            ParserWrapper {
                // .parser = .empty,
                parser: sgr::Parser::EMPTY,
                params_ptr: std::ptr::null_mut(),
                params_len: 0,
                // .alloc = alloc,
                alloc: alloc_.copied(),
            },
        )
    };
    if ptr.is_null() {
        return Result::OutOfMemory;
    }
    // result.* = ptr;
    // SAFETY: `result` is a valid writable pointer (caller contract).
    unsafe { *result = ptr };
    // return .success;
    Result::Success
}

/// PORT NOTE: `pub fn free(parser_) callconv(...) void`.
///
/// # Safety
/// `parser_`, if non-null, must be a pointer returned by `new`, not yet freed.
pub unsafe fn free(parser_: Parser) {
    // const wrapper = parser_ orelse return;
    if parser_.is_null() {
        return;
    }
    // const alloc = wrapper.alloc;
    // SAFETY: `parser_` is a valid `new`-returned pointer (caller contract).
    let alloc = unsafe { (*parser_).alloc };
    // const parser: *sgr.Parser = &wrapper.parser;
    // if (parser.params.len > 0) alloc.free(parser.params);
    unsafe { free_params(alloc.as_ref(), parser_) };
    // alloc.destroy(wrapper);
    unsafe { destroy(alloc.as_ref(), parser_) };
}

/// PORT NOTE: `pub fn reset(parser_) callconv(...) void`.
///
/// # Safety
/// `parser_`, if non-null, must be a pointer returned by `new`.
pub unsafe fn reset(parser_: Parser) {
    // const wrapper = parser_ orelse return;
    if parser_.is_null() {
        return;
    }
    // const parser: *sgr.Parser = &wrapper.parser;
    // parser.idx = 0;
    // SAFETY: `parser_` validity is the caller's contract.
    unsafe { (*parser_).parser.idx = 0 };
}

/// PORT NOTE: `pub fn setParams(parser_, params, seps_, len) callconv(...) Result`.
///
/// # Safety
/// `parser_`, if non-null, must be a pointer returned by `new`; `params` must
/// point to `len` readable `u16`; `seps_`, if non-null, must point to `len`
/// readable bytes.
pub unsafe fn set_params(
    parser_: Parser,
    params: *const u16,
    seps_: *const u8,
    len: usize,
) -> Result {
    // const wrapper = parser_ orelse return .invalid_value;
    if parser_.is_null() {
        return Result::InvalidValue;
    }
    // const alloc = wrapper.alloc;
    // const parser: *sgr.Parser = &wrapper.parser;
    // PORT NOTE (soundness): the reference holds `wrapper`/`parser` as live `*mut`
    // for the whole body, calling `alloc.free(parser.params)` partway through.
    // Zig pointers carry no aliasing protection, but a Rust `&mut *parser_` held
    // across the `free_params` call (which re-derives its own `&mut`) would be
    // invalidated under Stacked Borrows (see memory: rust-mut-args-strongly-
    // protected). So we operate through the raw `parser_` pointer and per-field
    // `addr_of_mut!`, never retaining a `&mut` across a call.
    // SAFETY: `parser_` validity is the caller's contract; reading the `Copy`
    // `alloc` field through the raw pointer aliases nothing.
    let alloc = unsafe { (*parser_).alloc };

    // Copy our new parameters
    // const params_slice = alloc.dupe(u16, params[0..len]) catch return .out_of_memory;
    // PORT NOTE: `alloc.dupe(u16, params[0..len])` allocates a fresh `[len]u16`
    // and copies the input. We allocate via the resolved allocator with the
    // `u16` layout (size = `len * 2`, align = 2) and copy the bytes in.
    let allocator = default(alloc.as_ref());
    let (new_ptr, new_len): (*mut u16, usize) = if len == 0 {
        // A zero-length dupe yields an empty (non-owning) slice; no allocation.
        (std::ptr::null_mut(), 0)
    } else {
        let byte_size = len * std::mem::size_of::<u16>();
        let raw = allocator.alloc(byte_size, Alignment::from_byte_units(align_of::<u16>()), 0)
            as *mut u16;
        if raw.is_null() {
            return Result::OutOfMemory;
        }
        // SAFETY: `params` is valid for `len` reads (caller contract); `raw` is a
        // freshly allocated, correctly aligned region of `len` `u16`s.
        unsafe { std::ptr::copy_nonoverlapping(params, raw, len) };
        (raw, len)
    };

    // if (parser.params.len > 0) alloc.free(parser.params);
    // PORT NOTE: free the previous backing buffer (the reference frees the prior
    // `parser.params` slice). Must happen before re-pointing `parser.params`.
    unsafe { free_params(alloc.as_ref(), parser_) };

    // parser.params = params_slice;
    // SAFETY: `parser_` is a valid `new`-returned pointer; the per-field raw
    // writes do not create an aliasing `&mut` over the wrapper.
    unsafe {
        std::ptr::addr_of_mut!((*parser_).params_ptr).write(new_ptr);
        std::ptr::addr_of_mut!((*parser_).params_len).write(new_len);
    }
    // SAFETY: the buffer at `(new_ptr, new_len)` is owned by the wrapper and lives
    // until the next `set_params`/`free`; the `'static` parser borrows it for
    // exactly that span (the wrapper never hands out the borrow past its own
    // lifetime).
    let new_params: &'static [u16] = if new_len == 0 {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(new_ptr, new_len) }
    };
    unsafe { std::ptr::addr_of_mut!((*parser_).parser.params).write(new_params) };

    // If we have separators, set that state too.
    // parser.params_sep = .initEmpty();
    unsafe {
        std::ptr::addr_of_mut!((*parser_).parser.params_sep).write(sgr::SepList::init_empty());
    }
    // if (seps_) |seps| {
    if !seps_.is_null() {
        // if (len > @TypeOf(parser.params_sep).bit_length) {
        // PORT NOTE: `@TypeOf(parser.params_sep).bit_length` is the bitset's bit
        // length. rustty's `sgr::SepList` is the `MAX_PARAMS == 24` deferred seam
        // (see rustty_vt::sgr); the bit length is that literal 24.
        const SEP_BIT_LENGTH: usize = 24;
        if len > SEP_BIT_LENGTH {
            // log.warn("ghostty_sgr_set_params: separators length {} exceeds max
            //   supported length {}", .{ len, @TypeOf(parser.params_sep).bit_length });
            crate::sys::log_fn(
                crate::sys::StdLevel::Warn,
                LOG_SCOPE,
                format_args!(
                    "rustty_sgr_set_params: separators length {len} exceeds max supported length {SEP_BIT_LENGTH}"
                ),
            );
            // return .invalid_value;
            return Result::InvalidValue;
        }

        // for (seps[0..len], 0..) |sep, i| { if (sep == ':') parser.params_sep.set(i); }
        // SAFETY: `seps_` is valid for `len` reads (caller contract).
        let seps = unsafe { std::slice::from_raw_parts(seps_, len) };
        for (i, &sep) in seps.iter().enumerate() {
            if sep == b':' {
                // SAFETY: `parser_` validity is the caller's contract; the
                // short-lived `&mut` to the bitset field does not outlive this call.
                unsafe { (*std::ptr::addr_of_mut!((*parser_).parser.params_sep)).set(i) };
            }
        }
    }

    // Reset our parsing state
    // parser.idx = 0;
    // SAFETY: `parser_` validity is the caller's contract.
    unsafe { std::ptr::addr_of_mut!((*parser_).parser.idx).write(0) };

    // return .success;
    Result::Success
}

/// Free the wrapper's owned `params` backing buffer, if any (`if
/// (parser.params.len > 0) alloc.free(parser.params)`).
///
/// # Safety
/// `parser_` must be a valid `new`-returned pointer.
unsafe fn free_params(alloc_: Option<&CAllocator>, parser_: Parser) {
    // PORT NOTE (soundness): operate through the raw pointer + `addr_of_mut!`, not
    // a retained `&mut *parser_`, so the caller's later raw writes are not
    // invalidated under Stacked Borrows.
    // SAFETY: `parser_` validity is the caller's contract; the `Copy` reads alias
    // nothing.
    let params_ptr = unsafe { (*parser_).params_ptr };
    let params_len = unsafe { (*parser_).params_len };
    if params_len > 0 && !params_ptr.is_null() {
        let allocator = default(alloc_);
        let byte_size = params_len * std::mem::size_of::<u16>();
        allocator.free(
            ZigSlice::new(params_ptr as *mut u8, byte_size),
            Alignment::from_byte_units(align_of::<u16>()),
            0,
        );
        // SAFETY: `parser_` validity is the caller's contract; per-field raw
        // writes avoid an aliasing `&mut` over the wrapper.
        unsafe {
            std::ptr::addr_of_mut!((*parser_).params_ptr).write(std::ptr::null_mut());
            std::ptr::addr_of_mut!((*parser_).params_len).write(0);
            std::ptr::addr_of_mut!((*parser_).parser.params).write(&[]);
        }
    }
}

/// PORT NOTE: `pub fn next(parser_, result: *sgr.Attribute.C) callconv(...) bool`.
///
/// # Safety
/// `parser_`, if non-null, must be a pointer returned by `new`; `result` must be
/// a valid, writable pointer to an `AttributeC`.
pub unsafe fn next(parser_: Parser, result: *mut AttributeC) -> bool {
    // const wrapper = parser_ orelse return false;
    if parser_.is_null() {
        return false;
    }
    // const parser: *sgr.Parser = &wrapper.parser;
    // SAFETY: `parser_` validity is the caller's contract.
    let parser = unsafe { &mut (*parser_).parser };
    // if (parser.next()) |attr| { result.* = attr.cval(); return true; }
    if let Some(attr) = parser.next() {
        // SAFETY: `result` is a valid writable pointer (caller contract).
        unsafe { *result = AttributeC::cval(attr) };
        return true;
    }

    // return false;
    false
}

/// PORT NOTE: `pub fn unknown_full(unknown: sgr.Attribute.Unknown.C, ptr:
/// ?*[*]const u16) callconv(...) usize`.
///
/// # Safety
/// `ptr`, if non-null, must be a valid, writable pointer to a `*const u16`.
pub unsafe fn unknown_full(unknown: UnknownC, ptr: *mut *const u16) -> usize {
    // if (ptr) |p| p.* = unknown.full_ptr;
    if !ptr.is_null() {
        // SAFETY: `ptr` is a valid writable pointer (caller contract).
        unsafe { *ptr = unknown.full_ptr };
    }
    // return unknown.full_len;
    unknown.full_len
}

/// PORT NOTE: `pub fn unknown_partial(unknown: sgr.Attribute.Unknown.C, ptr:
/// ?*[*]const u16) callconv(...) usize`.
///
/// # Safety
/// `ptr`, if non-null, must be a valid, writable pointer to a `*const u16`.
pub unsafe fn unknown_partial(unknown: UnknownC, ptr: *mut *const u16) -> usize {
    // if (ptr) |p| p.* = unknown.partial_ptr;
    if !ptr.is_null() {
        // SAFETY: `ptr` is a valid writable pointer (caller contract).
        unsafe { *ptr = unknown.partial_ptr };
    }
    // return unknown.partial_len;
    unknown.partial_len
}

/// PORT NOTE: `pub fn attribute_tag(attr: sgr.Attribute.C) callconv(...)
/// sgr.Attribute.Tag`.
/// D11 (P3-W6 T2): the return type is `c_int`, not `Tag`. The reference body is
/// a pure pass-through of the stored tag, and the stored tag is now the raw C
/// integer; re-narrowing it here would invent a failure mode the reference does
/// not have. ABI-identical (`RusttySgrAttributeTag` is an `int` enum).
pub fn attribute_tag(attr: AttributeC) -> c_int {
    // return attr.tag;
    attr.tag
}

/// PORT NOTE: `pub fn attribute_value(attr: *sgr.Attribute.C) callconv(...)
/// *sgr.Attribute.CValue`.
///
/// # Safety
/// `attr` must be a valid, readable/writable pointer to an `AttributeC`. The
/// returned pointer aliases `attr.value` and is valid as long as `attr` is.
pub unsafe fn attribute_value(attr: *mut AttributeC) -> *mut CValue {
    // return &attr.value;
    // SAFETY: `attr` validity is the caller's contract.
    unsafe { std::ptr::addr_of_mut!((*attr).value) }
}

// PORT NOTE (a8e9b413f): the reference DELETED `wasm_alloc_attribute` /
// `wasm_free_attribute` (and their `ghostty_wasm_alloc/free_sgr_attribute`
// exports + `terminal/c/main.zig` aliases) with the Wasm allocation API
// simplification: wasm hosts now allocate SGR attribute storage with the
// generic `ghostty_wasm_alloc(GhosttySgrAttribute.size)` instead.

#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_util::with_test_allocator;

    #[test]
    fn alloc() {
        with_test_allocator(|ta| {
            // var p: Parser = undefined;
            let mut p: Parser = std::ptr::null_mut();
            // try testing.expectEqual(Result.success, new(&lib.alloc.test_allocator, &p));
            assert_eq!(Result::Success, unsafe { new(Some(ta), &mut p) });
            // free(p);
            unsafe { free(p) };
        });
    }

    #[test]
    fn simple_params_no_seps() {
        with_test_allocator(|ta| {
            // var p: Parser = undefined;
            let mut p: Parser = std::ptr::null_mut();
            // try testing.expectEqual(Result.success, new(&lib.alloc.test_allocator, &p));
            assert_eq!(Result::Success, unsafe { new(Some(ta), &mut p) });
            // defer free(p);

            // try testing.expectEqual(Result.success, setParams(p, &.{1}, null, 1));
            let params1: [u16; 1] = [1];
            assert_eq!(Result::Success, unsafe {
                set_params(p, params1.as_ptr(), std::ptr::null(), 1)
            });

            // Set it twice on purpose to make sure we don't leak.
            // try testing.expectEqual(Result.success, setParams(p, &.{1}, null, 1));
            let params2: [u16; 1] = [1];
            assert_eq!(Result::Success, unsafe {
                set_params(p, params2.as_ptr(), std::ptr::null(), 1)
            });

            // Verify we get bold
            // var attr: sgr.Attribute.C = undefined;
            let mut attr: AttributeC = AttributeC {
                tag: Tag::Unset as c_int,
                value: CValue {
                    _padding: [0u64; 8],
                },
            };
            // try testing.expect(next(p, &attr));
            assert!(unsafe { next(p, &mut attr) });
            // try testing.expectEqual(.bold, attr.tag);
            assert_eq!(Tag::Bold as c_int, attr.tag);

            // Nothing else
            // try testing.expect(!next(p, &attr));
            assert!(!unsafe { next(p, &mut attr) });

            unsafe { free(p) };
        });
    }

    // task-14a (rustty-only proving test, NOT a reference test —
    // S177-F1/S5-F1): the separator-overflow warning used to bypass
    // `sys::log_fn` with an unconditional `eprintln!`. Proves it now reaches
    // the sink under the `sgr` scope.
    #[test]
    fn set_params_separator_overflow_warns_through_the_scoped_log_sink() {
        use crate::test_util::with_test_allocator as with_ta;
        use std::os::raw::c_void;
        let _guard = crate::sys::tests::reset_global();

        static CAPTURED: std::sync::Mutex<Vec<(crate::sys::LogLevel, String, String)>> =
            std::sync::Mutex::new(Vec::new());
        extern "C" fn log_cb(
            _userdata: *mut c_void,
            level: crate::sys::LogLevel,
            scope_ptr: *const u8,
            scope_len: usize,
            message_ptr: *const u8,
            message_len: usize,
        ) {
            // SAFETY: the sink hands us the scope/message byte ranges.
            let scope = unsafe { std::slice::from_raw_parts(scope_ptr, scope_len) };
            // SAFETY: as above.
            let message = unsafe { std::slice::from_raw_parts(message_ptr, message_len) };
            CAPTURED.lock().unwrap().push((
                level,
                String::from_utf8_lossy(scope).into_owned(),
                String::from_utf8_lossy(message).into_owned(),
            ));
        }
        CAPTURED.lock().unwrap().clear();

        with_ta(|ta| {
            let mut p: Parser = std::ptr::null_mut();
            assert_eq!(Result::Success, unsafe { new(Some(ta), &mut p) });

            assert_eq!(Result::Success, unsafe {
                crate::sys::set(crate::sys::Option_::Log, log_cb as *const c_void)
            });

            // 25 separators exceeds the SepList::MAX_PARAMS (24) bit length.
            let params: [u16; 25] = [1; 25];
            let seps: [u8; 25] = [b':'; 25];
            assert_eq!(Result::InvalidValue, unsafe {
                set_params(p, params.as_ptr(), seps.as_ptr(), 25)
            });

            assert_eq!(Result::Success, unsafe {
                crate::sys::set(crate::sys::Option_::Log, std::ptr::null())
            });

            unsafe { free(p) };
        });

        // FLAKE FIX (task 15, N28): compare only the entries on THIS test's own
        // log scope. The sys log callback is process-global, so a concurrently
        // running test's diagnostic lands in whichever buffer is installed; a
        // whole-buffer equality would then fail for a reason this test does not
        // control. Nothing else in the binary emits on this scope, so no
        // coverage is lost.
        let captured: Vec<_> = CAPTURED
            .lock()
            .unwrap()
            .iter()
            .filter(|(_, s, _)| s == super::LOG_SCOPE)
            .cloned()
            .collect();
        assert_eq!(
            captured,
            vec![(
                crate::sys::LogLevel::Warning,
                "sgr".to_string(),
                "rustty_sgr_set_params: separators length 25 exceeds max supported length 24"
                    .to_string(),
            )],
            "the S177-F1/S5-F1 warning was not routed through sys::log_fn"
        );
    }
}
